  function makeMap(){
    // Chunky code-native tiles; country coordinates and countries are separate from decorative coastlines.
    const polygons=[[[-168,68],[-140,72],[-115,65],[-90,72],[-60,50],[-82,25],[-100,16],[-115,30],[-125,48],[-160,58]],[[-80,12],[-62,8],[-35,-6],[-50,-30],[-70,-55],[-78,-16]],[[-12,36],[15,37],[40,12],[50,-10],[30,-35],[16,-34],[-2,4],[-18,18]],[[-10,36],[-6,56],[28,72],[65,68],[100,75],[160,60],[178,50],[140,35],[115,22],[106,0],[95,9],[78,8],[66,25],[42,30],[25,42]],[[-54,60],[-42,62],[-22,78],[-50,83],[-64,74]],[[112,-13],[135,-10],[153,-24],[144,-40],[116,-34]],[[47,-13],[51,-16],[48,-25],[44,-23]],[[130,31],[142,44],[146,42],[137,32]],[[96,6],[110,-5],[135,-7],[132,-10],[107,-8]],[[166,-35],[179,-39],[168,-48]]];
    function inside(x,y,poly){let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const [xi,yi]=poly[i],[xj,yj]=poly[j];if((yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)yes=!yes;}return yes;}
    let tiles='';for(let lat=-56;lat<=80;lat+=4)for(let lon=-176;lon<=180;lon+=4)if(polygons.some(p=>inside(lon,lat,p))){const x=(lon+180)/360*1000,y=(90-lat)/180*500;tiles+='<rect x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="9.5" height="9.5" fill="'+(((lon+lat)%12)?'#456582':'#729096')+'"/>';}
    const keys=Object.keys(DATA.labels),dots=keys.map(k=>{const [lon,lat]=COORDS[k];return '<rect x="'+((lon+180)/360*1000-3)+'" y="'+((90-lat)/180*500-3)+'" width="6" height="6" fill="'+(Object.values(PEOPLE).some(p=>p.country===k)?'#ffd183':'#74899e')+'"/>';}).join('');
    $('map').innerHTML='<svg viewBox="0 0 1000 500" role="img" aria-label="Пиксельная карта восьми направлений доставки. Выбор стран — в списке под картой."><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#31435b" stroke-width=".5"/></pattern></defs><rect width="1000" height="500" fill="url(#grid)"/>'+tiles+dots+'</svg>';
    $('countries').innerHTML=keys.map(k=>'<button type="button" class="country '+(Object.values(PEOPLE).some(p=>p.country===k)?'open':'')+'" data-country="'+k+'">'+DATA.labels[k].ru+'</button>').join('');
  }
