  const shuffle=items=>{const a=items.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
  function routeFor(id){return DATA.lanes.find(l=>l.id===ROUTES[id]);}
  function ensureShipments(id){const s=states[id],route=routeFor(id);if(!s.shipments)s.shipments=[];const seen=new Set();s.shipments=s.shipments.filter(x=>x.model<Math.floor(s.stage/2)&&!seen.has(x.model)&&seen.add(x.model));for(let i=0;i<Math.floor(s.stage/2);i++)if(!s.shipments.some(x=>x.model===i)){const now=Date.now();s.shipments.push({model:i,route:route.id,departedAt:now,arriveAt:now+route.days*1000});}}
  function allShipments(){return Object.entries(states).flatMap(([id,s])=>(s.shipments||[]).map(x=>({...x,supplier:id})));}
  function globalStats(){const values=Object.values(states),sum=k=>values.reduce((n,s)=>n+(s[k]||0),0);return {clicks:sum('clicks'),earned:sum('earned'),wins:sum('wins'),quizWins:sum('quizWins'),produced:values.reduce((n,s)=>n+Math.floor(s.stage/2),0),samples:values.reduce((n,s)=>n+Math.ceil(s.stage/2),0),trust:Math.max(...values.map(s=>s.trust)),delivered:allShipments().filter(x=>x.arriveAt<=Date.now()).length,suppliers:values.filter(s=>s.clicks>0).length,boards:sum('boards'),sets:sum('sets'),subs:sum('subs'),palettes:sum('palettes'),lunches:sum('lunches'),maxStreak:Math.max(...values.map(s=>s.maxStreak||0))};}
  function modelStatus(id,i){const s=states[id];if(s.stage<i*2)return 'Закрыто';if(s.stage===i*2)return 'Образец';if(s.stage===i*2+1)return 'Производство';const parcel=s.shipments.find(x=>x.model===i);return parcel&&parcel.arriveAt>Date.now()?'В пути · '+Math.ceil((parcel.arriveAt-Date.now())/1000)+' с':'В витрине';}
  function renderStore(){const parcels=allShipments(),arrived=parcels.filter(x=>x.arriveAt<=Date.now()),moving=parcels.filter(x=>x.arriveAt>Date.now());$('store-count').textContent=arrived.length+' / 192';$('shipping-count').textContent=moving.length;$('store-grid').innerHTML=arrived.length?arrived.map(x=>{const p=PEOPLE[x.supplier],m=p.models[x.model];return '<article class="catalog-row">'+modelIcon(m)+'<div><small>'+m[0]+'</small><h3>'+m[1]+'</h3><p>Произведено: '+DATA.labels[p.country].ru+'</p><p>Поставщик: '+p.name+'</p></div><span class="delivered-label">Доставлено</span></article>';}).join(''):'<p class="empty">Пока нет доставленных styles.</p>';$('shipping-grid').innerHTML=moving.length?moving.map(x=>'<article class="parcel">'+modelIcon(PEOPLE[x.supplier].models[x.model])+'<div><b>'+PEOPLE[x.supplier].models[x.model][1]+'</b><small>'+PEOPLE[x.supplier].name+'</small></div><strong>'+Math.ceil((x.arriveAt-Date.now())/1000)+' с</strong></article>').join(''):'<p class="micro">Все отправленные styles доставлены.</p>';renderSeason();}

