  function fillCell(cell){clock();const e=current().event;if(!e||e.type!=='board'||!e.cells.includes(cell)||e.filled.includes(cell))return false;e.filled.push(cell);if(e.filled.length===e.cells.length){if(!e.passes){e.passes=1;e.filled=e.cells.filter((_,i)=>i%2===0);e.left=Math.min(e.duration,e.left+3000);}else{finish(true,'Борд нарисован и готов к подписанию.');return true;}}save();renderEvent();return true;}
  function selectSet(i){clock();const e=current().event;if(!e||e.type!=='sets'||!e.order.includes(i)||e.matched.includes(i))return false;e.selected=i;save();renderEvent();return true;}
  function matchSet(source,target){clock();const e=current().event;if(!e||e.type!=='sets'||!e.order.includes(source)||!e.order.includes(target)||e.matched.includes(source)||e.matched.includes(target))return false;e.selected=null;if(source!==target){e.left=Math.max(0,e.left-4000);e.mistakes++;if(!e.left)finish(false,'Не все образцы развешены.');else{save();renderEvent();}return false;}e.matched.push(source);if(e.matched.length===e.order.length)finish(true,'Все комплекты на своих местах.');else{save();renderEvent();}return true;}
  function choosePalette(row,color){clock();const e=current().event;if(!e||e.type!=='palette'||!Number.isInteger(row)||row<0||row>3)return false;if(color===undefined)e.selected=row;else{if(!Number.isInteger(color)||color<0||color>3)return false;e.colors[row]=color;if(e.colors.every((c,i)=>c===e.targets[i])){finish(true,'Светлана утвердила палитру.');return true;}}save();renderEvent();return true;}
