  function initLanguage(){if(typeof MutationObserver==='undefined')return;const originals=new WeakMap(),attributes=new WeakMap();let obs;const sync=()=>{obs?.disconnect();const english=document.documentElement.lang==='en';const walk=document.createTreeWalker($('qg'),4);let node;while(node=walk.nextNode()){if(node.parentElement?.closest('style,script'))continue;let r=originals.get(node);if(!r||node.data!==r.last)r={ru:node.data,last:node.data};const out=english?translateText(r.ru):r.ru;if(node.data!==out)node.data=out;r.last=out;originals.set(node,r);}for(const element of root.querySelectorAll('[title],[aria-label],[alt]')){let map=attributes.get(element)||{};for(const key of ['title','aria-label','alt']){if(!element.hasAttribute(key))continue;const value=element.getAttribute(key);let r=map[key];if(!r||value!==r.last)r={ru:value,last:value};const out=english?translateText(r.ru):r.ru;if(value!==out)element.setAttribute(key,out);r.last=out;map[key]=r;}attributes.set(element,map);}obs.observe(root,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['title','aria-label','alt']});};obs=new MutationObserver(sync);new MutationObserver(sync).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});document.querySelectorAll('.lang-btn').forEach(b=>b.addEventListener('click',sync));sync();}



