  function cleanCopies(input,suppliers=states){const result=[];if(!Array.isArray(input))return result;for(const x of input){if(!x||!PEOPLE[x.supplier]||!Number.isInteger(x.model)||x.model<0||x.model>=24||suppliers[x.supplier].stage<x.model*2+2||!Number.isInteger(x.rarity)||x.rarity<1||x.rarity>3||!Number.isFinite(x.departedAt)||!Number.isFinite(x.arriveAt)||x.departedAt<0||x.arriveAt<x.departedAt||result.some(y=>y.supplier===x.supplier&&y.model===x.model&&y.rarity===x.rarity))continue;result.push({supplier:x.supplier,model:x.model,rarity:x.rarity,departedAt:x.departedAt,arriveAt:x.arriveAt});}return result.filter(x=>Array.from({length:x.rarity-1},(_,i)=>i+1).every(r=>result.some(y=>y.supplier===x.supplier&&y.model===x.model&&y.rarity===r)));}
  function nextRarity(id,index){return Math.max(0,...copies.filter(x=>x.supplier===id&&x.model===index).map(x=>x.rarity))+1;}
  function replicaPrice(index,rarity){return (index+1)*[0,1500,6000,18000][rarity];}
  function makeCopy(id,index){if(!PEOPLE[id]||!Number.isInteger(index)||index<0||index>=24)return false;const s=states[id],r=nextRarity(id,index);if(s.stage<index*2+2||r>3||copies.some(x=>x.supplier===id&&x.model===index&&x.arriveAt>Date.now()))return false;const price=replicaPrice(index,r);if(s.wallet<price)return false;s.wallet-=price;copies.push({supplier:id,model:index,rarity:r,departedAt:Date.now(),arriveAt:Date.now()+routeFor(id).days*1000});save();renderStore();if(screen==='play')render();else renderModels();return true;}
